<section class="status-strip" aria-label="Catalog overview"><div class="status-chip ok"><strong><?= count(array_filter($products,fn($p)=>(int)$p['active']===1)) ?></strong><span>Active products</span></div><div class="status-chip"><strong><?= count($products) ?></strong><span>Total products</span></div><div class="status-chip"><strong><?= e($currency) ?></strong><span>Catalog currency</span></div></section>
<section class="card"><div class="card-heading"><div><p class="section-kicker">Module-connected catalog</p><h2>Products</h2><p class="card-subtitle">Products remain attached to the industry module that enabled this store.</p></div><a class="btn" href="<?= e_attr($basePath) ?>/admin/store/products/edit">Add product</a></div><?php if (!$products): ?><div class="empty-state"><strong>No products yet</strong><span>Add the first item you want customers to order.</span></div><?php else: ?><div class="commerce-product-grid"><?php foreach($products as $p): ?><article class="commerce-product-card <?= !(int)$p['active']?'is-muted':'' ?>"><div class="commerce-product-art"><?php if($p['image_url']): ?><img src="<?= e_attr($p['image_url']) ?>" alt=""><?php else: ?><span aria-hidden="true">◇</span><?php endif; ?></div><div><div class="commerce-product-heading"><div><strong><?= e($p['name']) ?></strong><small><?= e($p['sku']) ?></small></div><span class="badge <?= (int)$p['active']?'ok':'neutral' ?>"><?= (int)$p['active']?'Active':'Hidden' ?></span></div><p><?= e($p['description']) ?></p><div class="commerce-product-meta"><strong><?= e($p['currency']) ?> $<?= number_format((int)$p['price_minor']/100,2) ?></strong><span><?= (int)$p['track_inventory']?'Stock: '.(int)$p['stock_quantity']:'Inventory not tracked' ?></span></div><div class="button-row"><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/store/products/edit&id=<?= (int)$p['id'] ?>">Edit</a><form method="post"><?= $csrf->field() ?><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><input type="hidden" name="action" value="<?= (int)$p['active']?'deactivate':'activate' ?>"><button class="btn small secondary"><?= (int)$p['active']?'Hide':'Activate' ?></button></form></div></div></article><?php endforeach; ?></div><?php endif; ?></section>
